#!/usr/bin/env bash
# Manage the n8n workflows on the EC2 host through n8n's own CLI (via SSM, no SSH, no API key).
#   scripts/n8n-workflows.sh import          import every n8n/workflows/*.json (same ids = update in place)
#   scripts/n8n-workflows.sh run <WF_ID>     execute a workflow once (its Manual trigger) and print the result
#   scripts/n8n-workflows.sh drill           error-path drill: E1 fails once on schedule, E must record it
# The JSON in n8n/workflows/ is generated by n8n/build_workflows.py (the source of truth).
set -euo pipefail
cd "$(dirname "$0")/.."
REGION="${AWS_REGION:-ap-southeast-2}"
BUCKET="$(scripts/stack-output.sh DataBucketName)"
INSTANCE="$(scripts/stack-output.sh N8nInstanceId)"
# n8n 2.x: a sub-workflow called from another workflow must be PUBLISHED. The parent
# workflows are published too once they are ready (that also arms their schedules).
PUBLISH_IDS="${PUBLISH_IDS:-LoanEngineWfA101 LoanEngineWfA001 LoanEngineWfB101 LoanEngineWfC101 LoanEngineWfC001 LoanEngineWfB001 LoanEngineWfE001}"

ssm() { # run shell commands on the instance, wait, print stdout (and stderr on failure)
  local id
  id="$(aws ssm send-command --region "$REGION" --instance-ids "$INSTANCE" --document-name AWS-RunShellScript \
    --timeout-seconds 900 --parameters "$(python3 -c 'import json,sys; print(json.dumps({"commands": sys.argv[1:], "executionTimeout": ["900"]}))' "$@")" \
    --query Command.CommandId --output text)"
  # Poll (the AWS waiter gives up after ~100 s; a crawl takes longer). A failed status call
  # (expired AWS session, no network) stops the script instead of looping forever.
  local status tries=0
  while true; do
    if ! status="$(aws ssm get-command-invocation --region "$REGION" --command-id "$id" \
                   --instance-id "$INSTANCE" --query Status --output text 2>/dev/null)"; then
      tries=$((tries + 1))
      if (( tries >= 6 )); then
        echo "cannot read the SSM command status (AWS session expired?); command id $id" >&2
        exit 1
      fi
      sleep 5; continue  # the invocation can take a moment to appear right after send-command
    fi
    [[ "$status" =~ ^(Pending|InProgress|Delayed)$ ]] || break
    sleep 5
  done
  aws ssm get-command-invocation --region "$REGION" --command-id "$id" --instance-id "$INSTANCE" \
    --query '[Status, StandardOutputContent, StandardErrorContent]' --output text
}

case "${1:-}" in
  import)
    aws s3 sync --region "$REGION" --delete n8n/workflows/ "s3://${BUCKET}/config/workflows/" --exclude "*" --include "*.json"
    ssm "rm -rf /opt/n8n/workflows && aws s3 sync --region $REGION s3://${BUCKET}/config/workflows/ /opt/n8n/workflows/ --only-show-errors" \
        "cd /opt/n8n && for f in workflows/*.json; do docker compose cp \$f n8n:/tmp/\$(basename \$f) && docker compose exec -T n8n n8n import:workflow --input=/tmp/\$(basename \$f) 2>&1 | tail -1; done" \
        "cd /opt/n8n && for id in ${PUBLISH_IDS}; do docker compose exec -T n8n n8n publish:workflow --id=\$id 2>&1 | grep -i publishing; done" \
        "cd /opt/n8n && docker compose restart n8n >/dev/null && for i in \$(seq 1 30); do curl -fsS localhost:5678/healthz >/dev/null 2>&1 && echo 'n8n restarted and healthy' && break; sleep 3; done"
    ;;
  run)
    wf="${2:?usage: $0 run <workflow-id>}"
    # A separate broker port: the running n8n already owns the default task-runner port.
    ssm "cd /opt/n8n && docker compose exec -T -e N8N_RUNNERS_BROKER_PORT=5690 n8n n8n execute --id=$wf --rawOutput 2>&1 | tail -c 20000"
    ;;
  drill)
    # Prove the real error path: publish E1 (a schedule that fails on purpose), let it fail ONCE
    # inside the n8n server, then unpublish it. Workflow E must record it in workflow_errors.
    ssm "cd /opt/n8n && docker compose exec -T n8n n8n publish:workflow --id=LoanEngineWfE101 2>&1 | grep -i publishing" \
        "cd /opt/n8n && docker compose restart n8n >/dev/null && sleep 80" \
        "cd /opt/n8n && docker compose exec -T n8n n8n unpublish:workflow --id=LoanEngineWfE101 2>&1 | tail -1" \
        "cd /opt/n8n && docker compose restart n8n >/dev/null && for i in \$(seq 1 30); do curl -fsS localhost:5678/healthz >/dev/null 2>&1 && echo 'E1 unpublished, n8n healthy' && break; sleep 3; done"
    ;;
  *) echo "usage: $0 import | run <WF_ID> | drill" >&2; exit 2 ;;
esac
